const { Server } = require('@hocuspocus/server');
const { authenticate } = require('./auth');

// No database persistence needed - Redmine stores the final documents.
// Hocuspocus only handles ephemeral real-time collaboration during editing.

// Fly.io uses PORT, Docker Compose uses HOCUSPOCUS_PORT
const port = parseInt(process.env.PORT || process.env.HOCUSPOCUS_PORT || '8081', 10);

// Shared secret for HMAC-signed tokens generated by Redmine.
// When set, every connection must present a valid token for the document it opens.
const tokenSecret = process.env.YJS_TOKEN_SECRET || '';

const server = new Server({
  // Ephemeral collaboration only: no onLoadDocument/onStoreDocument.
  // Redmine stores the final documents when users save.
  timeout: 30000,

  async onAuthenticate({ token, documentName }) {
    const user = authenticate({ token, secret: tokenSecret, documentName });

    console.log(`[Hocuspocus] ✅ Authenticated ${user.name} (${user.id}) for document: ${documentName}`);

    return { user };
  },

  async onConnect({ documentName, context }) {
    const user = context?.user || {};
    console.log(`[Hocuspocus] ✅ Client connected - User: ${user.name || 'Unknown'} (${user.id || 'unknown'}), Document: ${documentName}`);
  },

  async onDisconnect({ documentName, context }) {
    const user = context?.user || {};
    console.log(`[Hocuspocus] 👋 Client disconnected - User: ${user.name || 'Unknown'} (${user.id || 'unknown'}), Document: ${documentName}`);
  },
});

// Hocuspocus answers plain HTTP requests itself, so /health is a 200 out of the box.
server.listen(port).then(() => {
  console.log(`Hocuspocus server listening on port ${port}`);
  console.log(`WebSocket endpoint: ws://0.0.0.0:${port}/<document-name>`);
  console.log('Mode: Ephemeral collaboration (no persistence - Redmine stores final documents)');
  console.log(`Authentication: ${tokenSecret ? 'HMAC-signed tokens' : 'insecure development fallback'}`);
  console.log(`Health check: http://0.0.0.0:${port}/health`);
});
